#include "menu.h"

#include <stdio.h>
#include <string.h>

/**
 * main -- run the menu on the desktop.
 * With --demo it feeds a fixed script (help, one command, an unknown command, exit);
 * otherwise it reads lines from stdin until EXIT or end of input.
 * Returns: 0.
 */
int main(int argc, char **argv)
{
    char line[MENU_LINE_MAX + 16];

    Menu_Init();
    if (argc > 1 && strcmp(argv[1], "--demo") == 0) {
        static const char *const script[] = { "HELP", "VERSION", "no such command", "EXIT" };
        unsigned i;

        for (i = 0u; i < sizeof(script) / sizeof(script[0]); i++) {
            printf("> %s\n", script[i]);
            if (Menu_ProcessLine(script[i]) == MENU_EXIT) {
                break;
            }
        }
        return 0;
    }
    for (;;) {
        size_t n;

        printf("> ");
        fflush(stdout);
        if (fgets(line, (int)sizeof(line), stdin) == NULL) {
            break;
        }
        n = strlen(line);
        while (n > 0u && (line[n - 1u] == '\n' || line[n - 1u] == '\r')) {
            line[--n] = '\0';
        }
        if (Menu_ProcessLine(line) == MENU_EXIT) {
            break;
        }
    }
    return 0;
}
